// Reports a failed execution to Convex so it is visible in the admin panel.
// Only metadata is sent: no item data, which may contain personal details.
const crypto = require('crypto');
const secret = $env.LENDLOOP_CALLBACK_SECRET;
if (!secret || secret.length < 32) throw new Error('LENDLOOP_CALLBACK_SECRET is not configured');

const { execution = {}, workflow = {}, trigger } = $json;
const error = execution.error || (trigger && trigger.error) || {};
const message = String(error.message || 'Unknown error')
  .replace(/[^\s@]+@[^\s@]+/g, '[email]') // never forward addresses
  .slice(0, 500);

const path = '/n8n/workflow-failures';
const body = JSON.stringify({
  executionId: String(execution.id || `trigger-${Date.now()}`),
  workflowName: String(workflow.name || 'unknown'),
  lastNode: execution.lastNodeExecuted || (error.node && error.node.name) || undefined,
  message,
});
const ts = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${ts}.POST.${path}.${body}`).digest('hex');
console.error(`[LendLoop] workflow "${workflow.name}" failed at ${execution.lastNodeExecuted}: ${message}`);
return [{ json: { path, body, ts, signature } }];
